@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Poppins:wght@600;700;800&family=Playfair+Display:wght@600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --font-sans: 'Inter', sans-serif;
  --font-display: 'Poppins', 'Inter', sans-serif;

  /* Professional Blue Palette */
  --background: 210 40% 98%;
  --foreground: 222 47% 11%;

  --primary: 211 100% 50%; /* #007BFF */
  --primary-foreground: 210 40% 98%;

  --secondary: 210 40% 96%;
  --secondary-foreground: 222 47% 11%;

  --muted: 210 40% 96%;
  --muted-foreground: 215 16% 47%;

  --accent: 350 89% 60%; /* Canadian Red Accent */
  --accent-foreground: 210 40% 98%;

  --destructive: 0 84% 60%;
  --destructive-foreground: 210 40% 98%;

  --border: 214 32% 91%;
  --input: 214 32% 91%;
  --ring: 211 100% 50%;

  --radius: 0.75rem;
}

@layer base {
  body {
    @apply bg-background text-foreground antialiased font-sans selection:bg-primary/20 selection:text-primary;
  }

  h1, h2, h3, h4, h5, h6 {
    @apply font-display tracking-tight text-foreground;
  }
}

@layer utilities {
  .text-gradient {
    @apply bg-clip-text text-transparent bg-gradient-to-r from-primary to-blue-600;
  }

  .glass-card {
    @apply bg-white/80 backdrop-blur-md border border-white/20 shadow-xl;
  }

  .maple-bg {
    background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M30 0l-2.5 5 2.5 5 2.5-5-2.5-5zm0 15l-5 10 5 10 5-10-5-10zm15 0l-5 10 5 10 5-10-5-10zm-30 0l-5 10 5 10 5-10-5-10z' fill='%23007BFF' fill-opacity='0.03' fill-rule='evenodd'/%3E%3C/svg%3E");
  }
}

.hide-scrollbar::-webkit-scrollbar {
  display: none;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-track {
  background: hsl(var(--background));
}

::-webkit-scrollbar-thumb {
  background: hsl(var(--border));
  border-radius: 5px;
}

::-webkit-scrollbar-thumb:hover {
  background: hsl(var(--muted-foreground));
}

